from common import *
B='48遥控谋杀案.txt'
make('chen_baoming','陈宝明',B,
'陈宝明是拥有联合企业的工业家，有多个博士头衔，也以机械和发明才干受到业务竞争者云四风的尊重。他的宝记集团经营出现压力，面对与云氏集团合并的提议，他坚持独立经营，既有事业判断，也不愿个人声誉与地位因合并下降。新年舞会后，多名与股权相关的人离奇死亡，他又恰好逐一拜访股东争取支持，因而很快成为警方认定的嫌犯。他强硬、自傲、善于使用律师与诉讼，控告高翔，使对方暂被解除职务；这些行为加深了敌意，却不是他亲手制造谋杀的证据。实际上，他知道老友徐健的某些秘密，能在电话中以互知底细和胜诉把握施压，让徐健答应在董事会支持自己。这个选择也暴露了他的危险：他把知情当作商业筹码，没有及时把真相交给可靠的调查者。高翔潜入其书房后，为脱身用麻醉针令他昏迷。随后他遭到遥控谋杀，被布置成疑似自杀；正因为高翔知道他当时不可能自行开枪，这个伪装才被识破。终局应同时承认他被冤指为连环凶手、又会自私地利用秘密两点，而不把死者全部美化为无缺的正人。',
'被徐健谋杀并布置成疑似自杀；连环杀人嫌疑最终排除。','工业经营与机械素养','有发明与机械背景，能管理企业、评估合并、运用股权及诉讼谈判。','原文未展示他制造本案凶器；财富与学位不等于身体防护，掌握秘密也不能保证安全。',[(104,112,'竞争者对工业与发明才干的评价。'),(1384,1430,'诉讼、嫌疑与经营处境。'),(1700,1744,'反合并、以秘密施压。'),(1764,1770,'被高翔麻醉。'),(1918,1938,'被谋杀、伪自杀不成立。'),(2760,2766,'真凶与被利用的关系。')],
'维持自己创建事业的独立与地位，证明针对自己的指控错误。',[('企业合并会削弱自身地位','仍有可争取的股权','坚持独立并游说关键股东。'),('警方认定自己犯罪','认为可证明清白','诉诸律师和法庭，言辞可能加剧对立。'),('掌握朋友的不利秘密','需要对方支持商业选择','以互知底细施压，低估对方灭口风险。')],roles=('单书主角','阶段性对立者'),scores=(1,0,1,2,4,3),tier='并',dead=True)
make('xu_jian','徐健',B,
'徐健是提前退休的老将军，曾任工兵军官，有丰富的工程知识。他以健康不佳申请离职，军方此前怀疑通敌却未取得足够证据；他对没有被正式证明清白仍显愤愤不平。退休生活表面是浇花、太极、看战争电视片，家中却有设备齐全的机械工场和连通秘密机构的地下通道。他亲手制造遥控凶器，利用车辆、工作地点和目标固定习惯发动谋杀，又跟随陈宝明拜访股东的路线安排装置，使调查者误认工业家是凶手。他还在自己的摇椅下安排炸弹、佯作惊恐的受害者，以强化错误方向。掌握股份的目的不止发财，而是协助敌国控制宝记集团，把生产设施变成秘密兵工厂。陈宝明以秘密施压后，他进一步安排伪自杀灭口。木兰花和高翔来试探，他察觉问题而不急于答话，随后在工作室展示锤子伪装的低声枪械，把二人控制并交给地下枪手。他又想用假冒电话、麻醉气体和下水道转移制造远处的意外死亡，保存自己的清白外观。方局长查出旧地窖，援救队识破转移，徐健最终被捕并招认全部凶器出自自己之手。他的能力是真实的工程准备与欺骗，不是随念遥杀。',
'被警方逮捕，在证据下承认连续谋杀和亲手制作遥控凶器。','工程伪装与遥控机关','能制无线电触发装置、车辆控制、遥控枪械与炸药，以及外观为锤子的特殊枪。','每次须先安置装置并掌握目标位置与习惯；低声枪仍是物理武器，工场和地道是外部设施。',[(968,1002,'自演受害者的摇椅炸弹。'),(1954,1958,'提前退休及通敌怀疑。'),(2000,2096,'工程室、锤枪穿钢板与识破试探。'),(2142,2198,'股权及兵工厂计划。'),(2598,2614,'转移与伪电话计划。'),(2752,2766,'逮捕与认罪。')],
'完成敌国隐蔽工业计划并保住退休将军掩护，排除掌握秘密和阻碍股权控制的人。',[('目标有固定生活或工作位置','已能秘密接近现场','预置远控装置，等待有利时机。'),('自己可能被列入嫌疑','调查者已执着于另一人','扮演被害者，利用真装置制造可信危险。'),('来客以话语试探内幕','知道骗局可能破裂','表面不回应，再把人引到可控制的工场。')],roles=('反派',),scores=(4,0,2,3,5,4),tier='强')
make('baoji_spy_master','宝记计划间谍头目',B,
'这位未具姓名的中年人坐镇徐健住宅下的秘密机构，面颊瘦削，最初说话不急不徐，自信枪手、暗室与将军的表面信誉能够控制局势。他并不是退休将军的普通助手，而是敌国的间谍头目，目标是取得宝记集团控制权，逐步换入自己的人，把工业设备用于秘密军备生产。他向被押入的木兰花和高翔解释股东间互相优先收购的安排，承认通过杀害股东、安排陈宝明畏罪自杀，可以把股份集中到徐健手中。他以为只要给警方留下错误结案方向，计划就能继续，又试图用高额支票贿赂调查者。木兰花指出他无权轻易牺牲整个机构与最好掩护人时，他的镇定逐步瓦解，显出对上级责任和既有投入的畏惧。最后他依徐健的办法，用麻醉气体迷倒俘虏，准备经下水道转移并制造异地死亡。他谨慎绕过第一个出口，仍没有避开警方对周边的观察。持军用手枪押送时，云四风从远处以步枪击中其面部，他当场倒下，事后被确认死亡与真实身份。这个人会思考风险，也会因必须保住秘密行动而陷入自设限制，不能因是间谍头目就拥有整个敌国的无限资源。',
'押送俘虏转移时被云四风远距离击毙，身份查明为敌国间谍头目。','秘密行动组织与胁迫交涉','管理地下据点、枪手和转移路线，利用股权协定与贿赂推进隐蔽工业计划。','受上级授权和保密目标限制；手枪及人质不能阻挡远距离突袭，资源并非无限。',[(2122,2218,'头目性格、股权谋杀计划、贿赂与被指出的限制。'),(2600,2616,'麻醉转移安排。'),(2650,2694,'持枪押送并改变出口。'),(2720,2732,'被远射击倒。'),(2766,2766,'死亡身份与兵工厂目标。')],
'完成隐蔽军工计划，在不暴露机构与掩护人的条件下消除调查。',[('人质声称警方知道位置','还想保住秘密机构','以组织资源和谈判拖延，避免当场开杀。'),('对方识破自己无法轻易毁弃计划','威信受到直接挑战','由冷静转向恼怒，试图提高贿赂金额。'),('必须将俘虏转移','担忧出口被监视','使用麻醉和备用路线，却仍可能被远处观察发现。')],roles=('反派',),scores=(3,0,1,3,4,4),tier='强',dead=True)
